/**
 * Agent 13 — read-only household ↔ industry / energy linkage metadata (V10.13 boundary).
 * Never mutates household economy state; supplies ranking hints and guardian-facing notes only.
 */

export interface V1014HouseholdEnergyHint {
  regionId: string;
  concern: 'affordability' | 'essential_access' | 'employment_exposure';
  severity: 'low' | 'moderate' | 'high';
  relevanceDelta: number;
  reason: string;
  provenance: 'v1014_industrial_energy';
}

export interface V1014HouseholdLinkInputs {
  regionId: string;
  constraintBand: string;
  environmentalPressure: number;
  extractionBand: string;
  renewableBand: string;
  energyIndustryModifier: number | null;
}

const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, Number.isFinite(x) ? x : a));

export function buildHouseholdEnergyHints(input: V1014HouseholdLinkInputs): V1014HouseholdEnergyHint[] {
  const hints: V1014HouseholdEnergyHint[] = [];
  if (input.constraintBand === 'critical' || input.environmentalPressure >= 72) {
    hints.push({
      regionId: input.regionId,
      concern: 'essential_access',
      severity: 'high',
      relevanceDelta: clamp(-1.5 - input.environmentalPressure / 100, -2, -0.5),
      reason: `Environmental constraint ${input.constraintBand} may strain household essential access via energy network stress.`,
      provenance: 'v1014_industrial_energy',
    });
  } else if (input.constraintBand === 'constrained') {
    hints.push({
      regionId: input.regionId,
      concern: 'essential_access',
      severity: 'moderate',
      relevanceDelta: -0.75,
      reason: `Regional environmental constraints (${input.constraintBand}) add modest essential-access risk.`,
      provenance: 'v1014_industrial_energy',
    });
  }

  if (input.extractionBand === 'extreme' || input.extractionBand === 'intensive') {
    hints.push({
      regionId: input.regionId,
      concern: 'employment_exposure',
      severity: input.extractionBand === 'extreme' ? 'high' : 'moderate',
      relevanceDelta: clamp(0.4 + (input.extractionBand === 'extreme' ? 0.6 : 0.3), 0, 1.2),
      reason: `High extraction intensity (${input.extractionBand}) correlates with mining/energy employment exposure.`,
      provenance: 'v1014_industrial_energy',
    });
  }

  if (input.renewableBand === 'leading') {
    hints.push({
      regionId: input.regionId,
      concern: 'affordability',
      severity: 'low',
      relevanceDelta: 0.35,
      reason: 'Leading renewable share supports long-run household energy affordability (metadata only).',
      provenance: 'v1014_industrial_energy',
    });
  }

  if (input.energyIndustryModifier != null && input.energyIndustryModifier < -6) {
    hints.push({
      regionId: input.regionId,
      concern: 'affordability',
      severity: 'moderate',
      relevanceDelta: clamp(input.energyIndustryModifier / 20, -1.5, -0.2),
      reason: 'Energy industry output under environmental caps may pass through to household bills (bounded hint).',
      provenance: 'v1014_industrial_energy',
    });
  }

  return hints;
}

export function mergeHouseholdEnergyHints(
  lists: V1014HouseholdEnergyHint[][],
): V1014HouseholdEnergyHint[] {
  const byKey = new Map<string, V1014HouseholdEnergyHint>();
  for (const list of lists) {
    for (const h of list) {
      const key = `${h.regionId}:${h.concern}`;
      const prev = byKey.get(key);
      if (!prev || Math.abs(h.relevanceDelta) > Math.abs(prev.relevanceDelta)) {
        byKey.set(key, h);
      }
    }
  }
  return [...byKey.values()];
}


// --- bundled from modules/grid-recovery-extraction-efficiency.ts ---
/**
 * Agent 13 — slice 2: grid recovery pathways & regional extraction efficiency (read-only modifiers).
 */


export type V1014GridRecoveryBand = 'stalled' | 'gradual' | 'accelerating';

export interface V1014RegionalGridRecovery {
  regionId: string;
  band: V1014GridRecoveryBand;
  recoveryPoints: number;
  pressureRelief: number;
  summary: string;
}

export type V1014ExtractionEfficiencyBand = 'poor' | 'fair' | 'good' | 'leading';

export interface V1014RegionalExtractionEfficiency {
  regionId: string;
  score: number;
  band: V1014ExtractionEfficiencyBand;
  miningModifierBoost: number;
  summary: string;
}

const GRID_RECOVERY_PROJECT_BOOST: Record<string, number> = {
  renewable_grid: 6,
  battery_grid: 5,
  offshore_wind_farm: 4,
  pumped_hydro: 5,
  green_hydrogen_hub: 3,
  solar_farm: 2,
};

const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, Number.isFinite(x) ? x : a));

function bandRecovery(points: number): V1014GridRecoveryBand {
  if (points >= 14) return 'accelerating';
  if (points >= 6) return 'gradual';
  return 'stalled';
}

function bandEfficiency(score: number): V1014ExtractionEfficiencyBand {
  if (score >= 72) return 'leading';
  if (score >= 52) return 'good';
  if (score >= 34) return 'fair';
  return 'poor';
}

export function computeRegionalGridRecovery(params: {
  regionId: string;
  gridStressBand: V1014GridStressBand;
  gridStressPoints: number;
  renewableShareScore: number;
  completedProjectTypes: string[];
}): V1014RegionalGridRecovery {
  const { regionId, gridStressBand, gridStressPoints, renewableShareScore, completedProjectTypes } = params;
  if (gridStressPoints <= 0 || gridStressBand === 'stable') {
    return {
      regionId,
      band: 'accelerating',
      recoveryPoints: 0,
      pressureRelief: 0,
      summary: `Grid stable in ${regionId}; no recovery intervention required.`,
    };
  }

  let recoveryPoints = clamp(renewableShareScore / 12, 0, 8);
  if (renewableShareScore >= 55) recoveryPoints += 4;
  for (const pt of completedProjectTypes) {
    recoveryPoints += GRID_RECOVERY_PROJECT_BOOST[pt] || 0;
  }
  if (gridStressBand === 'critical') recoveryPoints *= 0.75;
  recoveryPoints = clamp(recoveryPoints, 0, 20);

  const band = bandRecovery(recoveryPoints);
  const pressureRelief = clamp(recoveryPoints * 0.65 + (band === 'accelerating' ? 2 : 0), 0, 14);
  const summary = `Grid recovery ${band} in ${regionId} (${recoveryPoints.toFixed(1)} pts) offsets ${pressureRelief.toFixed(1)} environmental pressure.`;

  return { regionId, band, recoveryPoints, pressureRelief, summary };
}

export interface V1014ExtractionSiteEfficiencySample {
  environmentalRisk: 'low' | 'moderate' | 'high';
  waterIntensity: number;
  emissionsIntensity: number;
  requiresPermit: boolean;
  rehabilitationYears: number;
}

export function computeRegionalExtractionEfficiency(params: {
  regionId: string;
  sites: V1014ExtractionSiteEfficiencySample[];
  renewableShareScore: number;
}): V1014RegionalExtractionEfficiency {
  const { regionId, sites, renewableShareScore } = params;
  if (!sites.length) {
    return {
      regionId,
      score: 50,
      band: 'fair',
      miningModifierBoost: 0,
      summary: `No registered extraction sites in ${regionId}; neutral efficiency assumed.`,
    };
  }

  const avgWater = sites.reduce((a, s) => a + s.waterIntensity, 0) / sites.length;
  const avgEmissions = sites.reduce((a, s) => a + s.emissionsIntensity, 0) / sites.length;
  const highRiskShare = sites.filter(s => s.environmentalRisk === 'high').length / sites.length;
  const permitShare = sites.filter(s => s.requiresPermit).length / sites.length;
  const rehabAvg = sites.reduce((a, s) => a + s.rehabilitationYears, 0) / sites.length;

  let score = 62;
  score -= avgWater * 18;
  score -= avgEmissions * 22;
  score -= highRiskShare * 16;
  score -= Math.max(0, rehabAvg - 5) * 2;
  score += permitShare * 4;
  score += clamp(renewableShareScore / 8, 0, 10);

  score = clamp(score, 0, 100);
  const band = bandEfficiency(score);
  const miningModifierBoost =
    band === 'leading' ? 3 : band === 'good' ? 1.5 : band === 'fair' ? 0 : -2;

  const summary = `Extraction efficiency ${band} in ${regionId} (score ${score.toFixed(0)}); bounded mining modifier ${miningModifierBoost >= 0 ? '+' : ''}${miningModifierBoost.toFixed(1)}.`;

  return { regionId, score, band, miningModifierBoost, summary };
}

export function nationalGridRecoveryIndex(recoveries: V1014RegionalGridRecovery[]): number {
  if (!recoveries.length) return 0;
  return recoveries.reduce((a, r) => a + r.recoveryPoints, 0) / recoveries.length;
}


// --- bundled from modules/regional-grid-scenarios-climate-transition.ts ---
/**
 * Agent 13 scale wave — regional grid scenarios & climate transition depth (read-only diagnostics).
 */


export type V1014GridScenarioArchetype =
  | 'baseline_interconnected'
  | 'renewable_export_corridor'
  | 'mining_demand_spike'
  | 'islanded_supply'
  | 'interconnector_constrained'
  | 'distributed_solar_ramp'
  | 'gas_peaker_reliance'
  | 'hydro_drought_coupling';

export interface V1014RegionalGridScenario {
  id: string;
  regionId: string;
  archetype: V1014GridScenarioArchetype;
  label: string;
  stressModifier: number;
  recoveryBias: number;
  renewableAffinity: number;
  documentation: string;
}

export type V1014ClimateTransitionStage =
  | 'legacy_heavy'
  | 'hybrid_transition'
  | 'accelerated_decarbonization'
  | 'net_zero_pathway';

export interface V1014ClimateTransitionProfile {
  stage: V1014ClimateTransitionStage;
  depth: number;
  momentum: number;
  summary: string;
}

const REGIONS = ['NSW', 'VIC', 'QLD', 'WA', 'SA', 'TAS', 'NT', 'ACT'] as const;

const ARCHETYPE_META: Record<
  V1014GridScenarioArchetype,
  { label: string; stress: number; recovery: number; ren: number; doc: string }
> = {
  baseline_interconnected: {
    label: 'Baseline NEM interconnection',
    stress: 0,
    recovery: 2,
    ren: 0.5,
    doc: 'Standard east-coast grid coupling; neutral scenario stress.',
  },
  renewable_export_corridor: {
    label: 'Renewable export corridor',
    stress: 4,
    recovery: 5,
    ren: 1.2,
    doc: 'High renewable output tests export limits and local grid hosting.',
  },
  mining_demand_spike: {
    label: 'Mining demand spike',
    stress: 8,
    recovery: 1,
    ren: -0.3,
    doc: 'Pilbara-style load ramps increase regional utilization without price mutation.',
  },
  islanded_supply: {
    label: 'Islanded regional supply',
    stress: 10,
    recovery: 3,
    ren: 0.2,
    doc: 'Weak interconnection raises local balancing risk.',
  },
  interconnector_constrained: {
    label: 'Interconnector constrained',
    stress: 7,
    recovery: 4,
    ren: 0.4,
    doc: 'Flow limits between regions amplify local bottlenecks.',
  },
  distributed_solar_ramp: {
    label: 'Distributed solar ramp',
    stress: 3,
    recovery: 6,
    ren: 1.0,
    doc: 'Rooftop and DER growth shifts midday net load patterns.',
  },
  gas_peaker_reliance: {
    label: 'Gas peaker reliance',
    stress: 6,
    recovery: 2,
    ren: -0.5,
    doc: 'Thermal firming dominates during renewable lulls.',
  },
  hydro_drought_coupling: {
    label: 'Hydro drought coupling',
    stress: 9,
    recovery: 2,
    ren: 0.1,
    doc: 'Storage drawdown links water stress to evening peak shortfall.',
  },
};

const ARCHETYPES = Object.keys(ARCHETYPE_META) as V1014GridScenarioArchetype[];

function regionalArchetypeOrder(regionId: string): V1014GridScenarioArchetype[] {
  const offset = REGIONS.indexOf(regionId as (typeof REGIONS)[number]);
  const rotated = [...ARCHETYPES.slice(offset % ARCHETYPES.length), ...ARCHETYPES.slice(0, offset % ARCHETYPES.length)];
  return rotated;
}

function buildScenarioCatalog(): V1014RegionalGridScenario[] {
  const out: V1014RegionalGridScenario[] = [];
  for (const regionId of REGIONS) {
    const order = regionalArchetypeOrder(regionId);
    order.forEach((archetype, idx) => {
      const meta = ARCHETYPE_META[archetype];
      const variant = idx + 1;
      out.push({
        id: `grid_sc_${regionId.toLowerCase()}_${archetype}_${variant}`,
        regionId,
        archetype,
        label: `${meta.label} — ${regionId} v${variant}`,
        stressModifier: meta.stress + (variant % 3),
        recoveryBias: meta.recovery + (variant % 2),
        renewableAffinity: meta.ren,
        documentation: `${meta.doc} Scenario variant ${variant} for ${regionId}.`,
      });
    });
  }
  return out;
}

export const V1014_REGIONAL_GRID_SCENARIOS: readonly V1014RegionalGridScenario[] = buildScenarioCatalog();

export const V1014_REGIONAL_GRID_SCENARIOS_BY_ID: Record<string, V1014RegionalGridScenario> = Object.fromEntries(
  V1014_REGIONAL_GRID_SCENARIOS.map(s => [s.id, s]),
);

export function selectRegionalGridScenario(params: {
  regionId: string;
  gridStressBand: V1014GridStressBand;
  renewableShareScore: number;
  extractionScore: number;
}): V1014RegionalGridScenario {
  const candidates = V1014_REGIONAL_GRID_SCENARIOS.filter(s => s.regionId === params.regionId);
  if (!candidates.length) {
    return V1014_REGIONAL_GRID_SCENARIOS[0];
  }
  let best = candidates[0];
  let bestScore = -Infinity;
  for (const c of candidates) {
    let score = c.recoveryBias - c.stressModifier * 0.2;
    score += c.renewableAffinity * (params.renewableShareScore / 40);
    if (params.gridStressBand === 'critical' || params.gridStressBand === 'bottlenecked') {
      score += c.stressModifier * 0.15;
    }
    score += params.extractionScore / 200;
    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return best;
}

const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, Number.isFinite(x) ? x : a));

export function computeClimateTransitionProfile(params: {
  renewableShareScore: number;
  extractionScore: number;
  environmentalPressure: number;
  gridStressPoints: number;
  renewableBand: string;
}): V1014ClimateTransitionProfile {
  const ren = params.renewableShareScore;
  const extract = params.extractionScore;
  const pressure = params.environmentalPressure;
  const grid = params.gridStressPoints;

  let depth = ren * 0.55 + Math.max(0, 40 - extract) * 0.35 - pressure * 0.25 - grid * 0.4;
  depth += params.renewableBand === 'leading' ? 12 : params.renewableBand === 'material' ? 6 : 0;
  depth = clamp(depth, 0, 100);

  let stage: V1014ClimateTransitionStage = 'legacy_heavy';
  if (depth >= 72) stage = 'net_zero_pathway';
  else if (depth >= 52) stage = 'accelerated_decarbonization';
  else if (depth >= 30) stage = 'hybrid_transition';

  const momentum = clamp((ren - extract * 0.3 - grid * 1.5) / 50, -1, 1);
  const summary = `Climate transition ${stage} (depth ${depth.toFixed(0)}, momentum ${momentum >= 0 ? '+' : ''}${momentum.toFixed(2)}).`;

  return { stage, depth, momentum, summary };
}

export function runV1014RegionalGridClimateScaleSelfTests(): {
  passed: number;
  failed: number;
  total: number;
} {
  let passed = 0;
  let failed = 0;
  const ok = (cond: boolean) => {
    if (cond) passed += 1;
    else failed += 1;
  };

  ok(V1014_REGIONAL_GRID_SCENARIOS.length === REGIONS.length * ARCHETYPES.length);
  ok(V1014_REGIONAL_GRID_SCENARIOS.every(s => s.id.startsWith('grid_sc_')));
  const wa = selectRegionalGridScenario({
    regionId: 'WA',
    gridStressBand: 'critical',
    renewableShareScore: 25,
    extractionScore: 70,
  });
  ok(wa.regionId === 'WA');
  const tr = computeClimateTransitionProfile({
    renewableShareScore: 65,
    extractionScore: 30,
    environmentalPressure: 40,
    gridStressPoints: 6,
    renewableBand: 'leading',
  });
  ok(tr.depth >= 30);
  ok(['hybrid_transition', 'accelerated_decarbonization', 'net_zero_pathway'].includes(tr.stage));

  return { passed, failed, total: passed + failed };
}


