export function sanitizeIndustrialEnergyEnvironmentalPersisted(raw: any, turn = 1): IndustrialEnergyEnvironmentalPersisted {
  const base = createInitialIndustrialEnergyEnvironmentalPersisted();
  if (!raw || typeof raw !== 'object') return base;
  if (raw.schemaVersion !== V1014_SCHEMA_VERSION) return base;
  return {
    schemaVersion: V1014_SCHEMA_VERSION,
    revision: Number(raw.revision) || 0,
    initializedTurn: typeof raw.initializedTurn === 'number' ? raw.initializedTurn : null,
    lastInputHash: String(raw.lastInputHash || ''),
    regionalHysteresis: typeof raw.regionalHysteresis === 'object' && raw.regionalHysteresis ? raw.regionalHysteresis : {},
    regionalPermitMemory: typeof raw.regionalPermitMemory === 'object' && raw.regionalPermitMemory ? raw.regionalPermitMemory : {},
    regionalCarbonMemory: typeof raw.regionalCarbonMemory === 'object' && raw.regionalCarbonMemory ? raw.regionalCarbonMemory : {},
    regionalWaterMemory: typeof raw.regionalWaterMemory === 'object' && raw.regionalWaterMemory ? raw.regionalWaterMemory : {},
    regionalBiodiversityMemory:
      typeof raw.regionalBiodiversityMemory === 'object' && raw.regionalBiodiversityMemory ? raw.regionalBiodiversityMemory : {},
    regionalCircularMemory: typeof raw.regionalCircularMemory === 'object' && raw.regionalCircularMemory ? raw.regionalCircularMemory : {},
    regionalHydrogenMemory: typeof raw.regionalHydrogenMemory === 'object' && raw.regionalHydrogenMemory ? raw.regionalHydrogenMemory : {},
    regionalMineralsMemory: typeof raw.regionalMineralsMemory === 'object' && raw.regionalMineralsMemory ? raw.regionalMineralsMemory : {},
    regionalOffshoreMemory: typeof raw.regionalOffshoreMemory === 'object' && raw.regionalOffshoreMemory ? raw.regionalOffshoreMemory : {},
    regionalDemandResponseMemory:
      typeof raw.regionalDemandResponseMemory === 'object' && raw.regionalDemandResponseMemory
        ? raw.regionalDemandResponseMemory
        : {},
    regionalCcsMemory: typeof raw.regionalCcsMemory === 'object' && raw.regionalCcsMemory ? raw.regionalCcsMemory : {},
    regionalFirmingMemory:
      typeof raw.regionalFirmingMemory === 'object' && raw.regionalFirmingMemory ? raw.regionalFirmingMemory : {},
    regionalRezMemory: typeof raw.regionalRezMemory === 'object' && raw.regionalRezMemory ? raw.regionalRezMemory : {},
    regionalBushfireMemory:
      typeof raw.regionalBushfireMemory === 'object' && raw.regionalBushfireMemory ? raw.regionalBushfireMemory : {},
    regionalRooftopDerMemory:
      typeof raw.regionalRooftopDerMemory === 'object' && raw.regionalRooftopDerMemory ? raw.regionalRooftopDerMemory : {},
    regionalEvV2gMemory: typeof raw.regionalEvV2gMemory === 'object' && raw.regionalEvV2gMemory ? raw.regionalEvV2gMemory : {},
    regionalAgrivoltaicsMemory:
      typeof raw.regionalAgrivoltaicsMemory === 'object' && raw.regionalAgrivoltaicsMemory ? raw.regionalAgrivoltaicsMemory : {},
    regionalSoilCarbonLandMemory:
      typeof raw.regionalSoilCarbonLandMemory === 'object' && raw.regionalSoilCarbonLandMemory
        ? raw.regionalSoilCarbonLandMemory
        : {},
    regionalGeothermalMemory:
      typeof raw.regionalGeothermalMemory === 'object' && raw.regionalGeothermalMemory ? raw.regionalGeothermalMemory : {},
    regionalIndustrialHeatMemory:
      typeof raw.regionalIndustrialHeatMemory === 'object' && raw.regionalIndustrialHeatMemory
        ? raw.regionalIndustrialHeatMemory
        : {},
    regionalBlueCarbonMemory:
      typeof raw.regionalBlueCarbonMemory === 'object' && raw.regionalBlueCarbonMemory ? raw.regionalBlueCarbonMemory : {},
    regionalShoreMarineMemory:
      typeof raw.regionalShoreMarineMemory === 'object' && raw.regionalShoreMarineMemory ? raw.regionalShoreMarineMemory : {},
    regionalLandfillWasteMemory:
      typeof raw.regionalLandfillWasteMemory === 'object' && raw.regionalLandfillWasteMemory ? raw.regionalLandfillWasteMemory : {},
    regionalDistrictHeatMemory:
      typeof raw.regionalDistrictHeatMemory === 'object' && raw.regionalDistrictHeatMemory ? raw.regionalDistrictHeatMemory : {},
    history: Array.isArray(raw.history) ? raw.history.slice(-V1014_LIMITS.maxHistory) : [],
  };
}

function v1014BandExtraction(score: number): V1014ExtractionBand {
  if (score >= 78) return 'extreme';
  if (score >= 58) return 'intensive';
  if (score >= 32) return 'moderate';
  return 'dormant';
}

function v1014BandRenewable(share: number): V1014RenewableBand {
  if (share >= 0.55) return 'leading';
  if (share >= 0.35) return 'material';
  if (share >= 0.18) return 'emerging';
  return 'minimal';
}

function v1014BandConstraint(pressure: number): V1014ConstraintBand {
  if (pressure >= 72) return 'critical';
  if (pressure >= 52) return 'constrained';
  if (pressure >= 30) return 'watch';
  return 'clear';
}

export function industrialEnergyEnvironmentalInputHash(i: IndustrialEnergyEnvironmentalInputs): string {
  let h = 2166136261 >>> 0;
  const mix = (s: string) => { for (let k = 0; k < s.length; k++) { h ^= s.charCodeAt(k); h = Math.imul(h, 16777619) >>> 0; } };
  mix(`t${i.turn}|e${i.enabled ? 1 : 0}|ns${i.nationalSystems?.inputHash || ''}|sc${i.industries?.revision || ''}`);
  (i.crises || []).forEach(c => mix(`${c.id}${c.status}`));
  i.completedProjectTypes.sort().forEach(p => mix(p));
  return h.toString(36);
}

function v1014RegionSector(lr: any, regionId: string, sector: string): number {
  const reg = lr?.regions?.[regionId];
  if (!reg?.sectors) return 0;
  return v1014Clamp(Number(reg.sectors[sector]) || 0, 0, 100);
}

function v1014IndustryStrength(ind: IndustriesSupplyChainsState | null, regionId: string, industry: 'mining' | 'energy' | 'manufacturing', lr?: any): number {
  const st = ind?.regions?.[regionId]?.industries?.[industry];
  if (st && st.strength >= 5) return v1014Clamp(st.strength, 0, 100);
  const sector = industry === 'mining' ? 'mining' : industry === 'energy' ? 'energy' : 'manufacturing';
  return v1014Clamp(v1014RegionSector(lr, regionId, sector) * 0.85, 0, 100);
}

export function buildIndustrialEnergyEnvironmentalInputs(params: {
  turn: number;
  enabled: boolean;
  gameState: any;
  gameSettings: any;
  livingRegions: any;
  nationalSystems: NationalSystemsState | null;
  industries: IndustriesSupplyChainsState | null;
  regionalFactions: RegionalFactionsState | null;
}): IndustrialEnergyEnvironmentalInputs {
  const gs = params.gameState || {};
  const projects = Object.values(gs.infrastructureProjects || {}) as any[];
  const completedProjectTypes = projects.filter(p => p && (p.status === 'completed' || p.status === 'upgraded')).map(p => String(p.projectType || p.type || ''));
  const crisesRaw = gs.crisisChainState?.activeCrises || gs.activeCrises || [];
  const crises = (Array.isArray(crisesRaw) ? crisesRaw : Object.values(crisesRaw || {})).filter(Boolean).map((c: any) => ({
    id: String(c.id || c.crisisId || 'crisis'),
    status: String(c.status || 'active'),
    category: String(c.category || ''),
    affectedRegions: Array.isArray(c.affectedRegions) ? c.affectedRegions : [],
  }));
  return {
    turn: params.turn,
    enabled: params.enabled,
    livingRegions: params.livingRegions,
    nationalSystems: params.nationalSystems,
    industries: params.industries,
    regionalFactions: params.regionalFactions,
    crises,
    completedProjectTypes,
  };
}

export function computeIndustrialEnergyEnvironmentalState(
  inputs: IndustrialEnergyEnvironmentalInputs,
  rawPersisted?: IndustrialEnergyEnvironmentalPersisted | null,
  prev?: IndustrialEnergyEnvironmentalState | null
): { state: IndustrialEnergyEnvironmentalState; persisted: IndustrialEnergyEnvironmentalPersisted } {
  const turn = Math.max(1, Math.floor(Number(inputs.turn) || 1));
  const persisted = sanitizeIndustrialEnergyEnvironmentalPersisted(rawPersisted, turn);
  const inputHash = industrialEnergyEnvironmentalInputHash(inputs);
  if (!inputs.enabled) {
    const empty: IndustrialEnergyEnvironmentalState = {
      schemaVersion: V1014_SCHEMA_VERSION,
      revision: persisted.revision,
      turn,
      inputHash,
      regions: {},
      national: {
        extractionBand: 'dormant',
        renewableBand: 'minimal',
        constraintBand: 'clear',
        nationalRenewableShare: 0,
        nationalExtractionIntensity: 0,
        topConstrainedRegions: [],
        topRenewableRegions: [],
        primaryEnvironmentalDomain: null,
        summary: 'Industrial energy & environmental layer disabled.',
      },
      industryModifiers: [],
      householdEnergyHints: [],
      interRegionalFlows: [],
      turnSimulationDigest: `t${turn}|disabled`,
      regionalPermitLedgers: {},
      regionalEmissionsLedgers: {},
      regionalWaterLedgers: {},
      regionalBiodiversityLedgers: {},
      regionalCircularLedgers: {},
      regionalHydrogenLedgers: {},
      regionalMineralsLedgers: {},
      regionalOffshoreLedgers: {},
      regionalDemandResponseLedgers: {},
      regionalCcsLedgers: {},
      regionalFirmingLedgers: {},
      regionalRezLedgers: {},
      regionalBushfireLedgers: {},
      regionalRooftopDerLedgers: {},
      regionalEvV2gLedgers: {},
      regionalAgrivoltaicsLedgers: {},
      regionalSoilCarbonLandLedgers: {},
      regionalGeothermalLedgers: {},
      regionalIndustrialHeatDecarbLedgers: {},
      regionalBlueCarbonCoastalLedgers: {},
      regionalShoreMarineEnergyLedgers: {},
      regionalLandfillWasteEnergyLedgers: {},
      regionalDistrictRenewableHeatLedgers: {},
      transitions: [],
      history: persisted.history,
    };
    return { state: empty, persisted: { ...persisted, lastInputHash: inputHash } };
  }
  if (persisted.lastInputHash === inputHash && prev && prev.inputHash === inputHash) {
    return { state: prev, persisted };
  }

  const lr = inputs.livingRegions;
  const regions: Record<string, V1014RegionalEnergyProfile> = {};
  const modifiers: V1014IndustryModifierEntry[] = [];
  const householdHintLists: V1014HouseholdEnergyHint[][] = [];
  const permitLedgers: Record<string, V1014RegionalPermitLedger> = {};
  const emissionsLedgers: Record<string, V1014RegionalEmissionsLedger> = {};
  const waterLedgers: Record<string, V1014RegionalWaterLedger> = {};
  const biodiversityLedgers: Record<string, V1014RegionalBiodiversityLedger> = {};
  const circularLedgers: Record<string, V1014RegionalCircularLedger> = {};
  const hydrogenLedgers: Record<string, V1014RegionalHydrogenLedger> = {};
  const mineralsLedgers: Record<string, V1014RegionalMineralsLedger> = {};
  const offshoreLedgers: Record<string, V1014RegionalOffshoreMarineLedger> = {};
  const demandResponseLedgers: Record<string, V1014RegionalDemandResponseLedger> = {};
  const ccsLedgers: Record<string, V1014RegionalCcsHubLedger> = {};
  const firmingLedgers: Record<string, V1014RegionalGridFirmingLedger> = {};
  const rezLedgers: Record<string, V1014RegionalRezTransmissionLedger> = {};
  const bushfireLedgers: Record<string, V1014RegionalBushfireResilienceLedger> = {};
  const rooftopDerLedgers: Record<string, V1014RegionalRooftopDerLedger> = {};
  const evV2gLedgers: Record<string, V1014RegionalEvV2gFleetLedger> = {};
  const agrivoltaicsLedgers: Record<string, V1014RegionalAgrivoltaicsLedger> = {};
  const soilCarbonLandLedgers: Record<string, V1014RegionalSoilCarbonLandLedger> = {};
  const geothermalLedgers: Record<string, V1014RegionalGeothermalLedger> = {};
  const industrialHeatDecarbLedgers: Record<string, V1014RegionalIndustrialHeatDecarbLedger> = {};
  const blueCarbonCoastalLedgers: Record<string, V1014RegionalBlueCarbonCoastalLedger> = {};
  const shoreMarineEnergyLedgers: Record<string, V1014RegionalShoreMarineEnergyLedger> = {};
  const landfillWasteEnergyLedgers: Record<string, V1014RegionalLandfillWasteEnergyLedger> = {};
  const districtRenewableHeatLedgers: Record<string, V1014RegionalDistrictRenewableHeatLedger> = {};
  const nextPermitMemory: Record<string, { utilized: number }> = { ...persisted.regionalPermitMemory };
  const nextCarbonMemory: Record<string, { creditBalance: number; netEmissionsIndex: number }> = {
    ...persisted.regionalCarbonMemory,
  };
  const nextWaterMemory: Record<string, { allocationUsed: number }> = { ...persisted.regionalWaterMemory };
  const nextBiodiversityMemory: Record<string, { offsetBalance: number; stewardshipIndex: number }> = {
    ...persisted.regionalBiodiversityMemory,
  };
  const nextCircularMemory: Record<string, { recoveryIndex: number }> = { ...persisted.regionalCircularMemory };
  const nextHydrogenMemory: Record<string, { electrolyserBalance: number; exportIndex: number }> = {
    ...persisted.regionalHydrogenMemory,
  };
  const nextMineralsMemory: Record<string, { securityIndex: number }> = { ...persisted.regionalMineralsMemory };
  const nextOffshoreMemory: Record<string, { leaseBalance: number; marineIndex: number }> = {
    ...persisted.regionalOffshoreMemory,
  };
  const nextDemandResponseMemory: Record<string, { flexIndex: number }> = { ...persisted.regionalDemandResponseMemory };
  const nextCcsMemory: Record<string, { injectionBalance: number; captureIndex: number }> = {
    ...persisted.regionalCcsMemory,
  };
  const nextFirmingMemory: Record<string, { firmingIndex: number }> = { ...persisted.regionalFirmingMemory };
  const nextRezMemory: Record<string, { spillBalance: number; backboneIndex: number }> = { ...persisted.regionalRezMemory };
  const nextBushfireMemory: Record<string, { resilienceIndex: number }> = { ...persisted.regionalBushfireMemory };
  const nextRooftopDerMemory: Record<string, { exportBalance: number; derIndex: number }> = {
    ...persisted.regionalRooftopDerMemory,
  };
  const nextEvV2gMemory: Record<string, { fleetIndex: number }> = { ...persisted.regionalEvV2gMemory };
  const nextAgrivoltaicsMemory: Record<string, { paddockBalance: number; dualUseIndex: number }> = {
    ...persisted.regionalAgrivoltaicsMemory,
  };
  const nextSoilCarbonLandMemory: Record<string, { stewardshipIndex: number }> = {
    ...persisted.regionalSoilCarbonLandMemory,
  };
  const nextGeothermalMemory: Record<string, { reservoirBalance: number; thermalIndex: number }> = {
    ...persisted.regionalGeothermalMemory,
  };
  const nextIndustrialHeatMemory: Record<string, { decarbIndex: number }> = { ...persisted.regionalIndustrialHeatMemory };
  const nextBlueCarbonMemory: Record<string, { wetlandBalance: number; sinkIndex: number }> = {
    ...persisted.regionalBlueCarbonMemory,
  };
  const nextShoreMarineMemory: Record<string, { shoreIndex: number }> = { ...persisted.regionalShoreMarineMemory };
  const nextLandfillWasteMemory: Record<string, { captureBalance: number; methaneIndex: number }> = {
    ...persisted.regionalLandfillWasteMemory,
  };
  const nextDistrictHeatMemory: Record<string, { thermalIndex: number }> = { ...persisted.regionalDistrictHeatMemory };
  const transitions: IndustrialEnergyEnvironmentalState['transitions'] = [];
  const nextHyst = { ...persisted.regionalHysteresis };

  for (const regionId of V1014_CORE_REGIONS) {
    const sites = V1014_EXTRACTION_SITES.filter(s => s.regionId === regionId);
    const assets = V1014_RENEWABLE_ASSETS.filter(a => a.regionId === regionId);
    const miningSec = v1014RegionSector(lr, regionId, 'mining');
    const renSec = v1014RegionSector(lr, regionId, 'renewables');
    const energySec = v1014RegionSector(lr, regionId, 'energy');
    const mfgSec = v1014RegionSector(lr, regionId, 'manufacturing');
    const miningStr = v1014IndustryStrength(inputs.industries, regionId, 'mining', lr);
    const energyStr = v1014IndustryStrength(inputs.industries, regionId, 'energy', lr);
    const mfgStr = v1014IndustryStrength(inputs.industries, regionId, 'manufacturing', lr);

    const siteIntensity = sites.reduce((a, s) => a + (s.environmentalRisk === 'high' ? 3 : s.environmentalRisk === 'moderate' ? 2 : 1), 0);
    const rawExtract = v1014Clamp(miningSec * 0.45 + energySec * 0.25 + siteIntensity * 4 + miningStr * 0.35, 0, 100);
    const renMw = assets.reduce((a, r) => a + r.installedMw * r.capacityFactor, 0);
    const fossilProxy = v1014Clamp(energySec + miningSec * 0.2 + siteIntensity * 2, 1, 120);
    const rawRenewShare = v1014Clamp((renSec * 0.4 + renMw / 8) / fossilProxy, 0, 1.2);

    const prevH = nextHyst[regionId] || { extractionScore: rawExtract, renewableScore: rawRenewShare * 100, pressure: 0 };
    const smooth = V1014_LIMITS.renewableShareSmoothing;
    const extractionScore = v1014Round(prevH.extractionScore * (1 - smooth) + rawExtract * smooth, 1);
    const renewableShareScore = v1014Round(prevH.renewableScore * (1 - smooth) + rawRenewShare * 100 * smooth, 1);

    const energyNet = inputs.nationalSystems?.regions?.[regionId]?.networks?.energy;
    const gridStress = computeRegionalGridStress(regionId, inputs.nationalSystems, renewableShareScore);
    const energyStress = gridStress.stressPoints;

    const climateHazards = detectClimateHazardsFromCrises(inputs.crises || [], regionId);
    const climatePressure = aggregateClimatePressure(climateHazards);

    const gridRecovery = computeRegionalGridRecovery({
      regionId,
      gridStressBand: gridStress.band,
      gridStressPoints: gridStress.stressPoints,
      renewableShareScore,
      completedProjectTypes: inputs.completedProjectTypes || [],
    });

    const extractionEfficiency = computeRegionalExtractionEfficiency({
      regionId,
      sites,
      renewableShareScore,
    });

    const gridScenario = selectRegionalGridScenario({
      regionId,
      gridStressBand: gridStress.band,
      renewableShareScore,
      extractionScore,
    });

    const storageFlex = computeRegionalStorageFlexibility({
      regionId,
      renewableShareScore,
      gridStressPoints: gridStress.stressPoints,
      completedProjectTypes: inputs.completedProjectTypes || [],
    });

    const highRiskCount = sites.filter(s => s.environmentalRisk === 'high').length;
    const permitStep = advanceRegionalPermitLedger({
      regionId,
      siteCount: sites.length,
      highRiskSiteCount: highRiskCount,
      extractionScore,
      prev: nextPermitMemory[regionId] || null,
    });
    nextPermitMemory[regionId] = permitStep.next;
    permitLedgers[regionId] = permitStep.ledger;

    const siteEmissionsLoad = sites.reduce((a, s) => a + s.emissionsIntensity, 0) / Math.max(1, sites.length);
    const waterIntensityLoad = sites.reduce((a, s) => a + s.waterIntensity, 0) / Math.max(1, sites.length);
    const emissionsStep = computeRegionalEmissionsLedger({
      regionId,
      extractionScore,
      renewableShareScore,
      siteEmissionsLoad,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextCarbonMemory[regionId] || null,
    });
    nextCarbonMemory[regionId] = emissionsStep.next;
    emissionsLedgers[regionId] = emissionsStep.ledger;

    const waterStep = advanceRegionalWaterAllocation({
      regionId,
      waterIntensityLoad,
      climateHazardPressure: climatePressure,
      extractionScore,
      emissionsBand: emissionsStep.ledger.band,
      prev: nextWaterMemory[regionId] || null,
    });
    nextWaterMemory[regionId] = waterStep.next;
    waterLedgers[regionId] = waterStep.ledger;

    const biodiversityStep = computeRegionalBiodiversityLedger({
      regionId,
      extractionScore,
      highRiskSiteCount: highRiskCount,
      waterStressPressure: waterStep.ledger.pressureAdd,
      emissionsPressureRelief: emissionsStep.ledger.pressureRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextBiodiversityMemory[regionId] || null,
    });
    nextBiodiversityMemory[regionId] = biodiversityStep.next;
    biodiversityLedgers[regionId] = biodiversityStep.ledger;

    const circularStep = advanceRegionalCircularRecovery({
      regionId,
      extractionScore,
      renewableShareScore,
      biodiversityBand: biodiversityStep.ledger.band,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextCircularMemory[regionId] || null,
    });
    nextCircularMemory[regionId] = circularStep.next;
    circularLedgers[regionId] = circularStep.ledger;

    const hydrogenStep = computeRegionalHydrogenLedger({
      regionId,
      renewableShareScore,
      gridStressPoints: gridStress.stressPoints,
      circularRecoveryRelief: circularStep.ledger.circularRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextHydrogenMemory[regionId] || null,
    });
    nextHydrogenMemory[regionId] = hydrogenStep.next;
    hydrogenLedgers[regionId] = hydrogenStep.ledger;

    const mineralsStep = advanceRegionalMineralsSupply({
      regionId,
      extractionScore,
      miningIndustryStrength: miningStr,
      hydrogenBand: hydrogenStep.ledger.band,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextMineralsMemory[regionId] || null,
    });
    nextMineralsMemory[regionId] = mineralsStep.next;
    mineralsLedgers[regionId] = mineralsStep.ledger;

    const offshoreStep = computeRegionalOffshoreMarineLedger({
      regionId,
      renewableShareScore,
      gridStressPoints: gridStress.stressPoints,
      hydrogenGridRelief: hydrogenStep.ledger.hydrogenGridRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextOffshoreMemory[regionId] || null,
    });
    nextOffshoreMemory[regionId] = offshoreStep.next;
    offshoreLedgers[regionId] = offshoreStep.ledger;

    const demandStep = advanceRegionalDemandResponse({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      hydrogenGridRelief: hydrogenStep.ledger.hydrogenGridRelief,
      offshoreBand: offshoreStep.ledger.band,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextDemandResponseMemory[regionId] || null,
    });
    nextDemandResponseMemory[regionId] = demandStep.next;
    demandResponseLedgers[regionId] = demandStep.ledger;

    const ccsStep = computeRegionalCcsHubLedger({
      regionId,
      extractionScore,
      emissionsPressureRelief: emissionsStep.ledger.pressureRelief,
      netEmissionsIndex: emissionsStep.ledger.netEmissionsIndex,
      demandFlexRelief: demandStep.ledger.demandFlexRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextCcsMemory[regionId] || null,
    });
    nextCcsMemory[regionId] = ccsStep.next;
    ccsLedgers[regionId] = ccsStep.ledger;

    const firmingStep = advanceRegionalGridFirming({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      renewableShareScore,
      ccsBand: ccsStep.ledger.band,
      offshoreRenewableRelief: offshoreStep.ledger.offshoreRenewableRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextFirmingMemory[regionId] || null,
    });
    nextFirmingMemory[regionId] = firmingStep.next;
    firmingLedgers[regionId] = firmingStep.ledger;

    const rezStep = computeRegionalRezTransmissionLedger({
      regionId,
      renewableShareScore,
      gridFirmingRelief: firmingStep.ledger.gridFirmingRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextRezMemory[regionId] || null,
    });
    nextRezMemory[regionId] = rezStep.next;
    rezLedgers[regionId] = rezStep.ledger;

    const bushfireStep = advanceRegionalBushfireResilience({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      climateHazardPressure: climatePressure,
      rezBand: rezStep.ledger.band,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextBushfireMemory[regionId] || null,
    });
    nextBushfireMemory[regionId] = bushfireStep.next;
    bushfireLedgers[regionId] = bushfireStep.ledger;

    const derStep = computeRegionalRooftopDerLedger({
      regionId,
      renewableShareScore,
      demandFlexRelief: demandStep.ledger.demandFlexRelief,
      bushfireGridRelief: bushfireStep.ledger.bushfireGridRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextRooftopDerMemory[regionId] || null,
    });
    nextRooftopDerMemory[regionId] = derStep.next;
    rooftopDerLedgers[regionId] = derStep.ledger;

    const v2gStep = advanceRegionalEvV2gFleet({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      rooftopDerBand: derStep.ledger.band,
      rezSpillRelief: rezStep.ledger.rezSpillRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextEvV2gMemory[regionId] || null,
    });
    nextEvV2gMemory[regionId] = v2gStep.next;
    evV2gLedgers[regionId] = v2gStep.ledger;

    const agriStep = computeRegionalAgrivoltaicsLedger({
      regionId,
      renewableShareScore,
      landStewardshipRelief: biodiversityStep.ledger.landStewardshipRelief,
      circularRecoveryRelief: circularStep.ledger.circularRelief,
      evV2gGridRelief: v2gStep.ledger.evV2gGridRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextAgrivoltaicsMemory[regionId] || null,
    });
    nextAgrivoltaicsMemory[regionId] = agriStep.next;
    agrivoltaicsLedgers[regionId] = agriStep.ledger;

    const soilStep = advanceRegionalSoilCarbonLand({
      regionId,
      extractionScore,
      waterStressPressure: waterStep.ledger.pressureAdd,
      agrivoltaicsBand: agriStep.ledger.band,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextSoilCarbonLandMemory[regionId] || null,
    });
    nextSoilCarbonLandMemory[regionId] = soilStep.next;
    soilCarbonLandLedgers[regionId] = soilStep.ledger;

    const geoStep = computeRegionalGeothermalLedger({
      regionId,
      extractionScore,
      agrivoltaicsLandRelief: agriStep.ledger.agrivoltaicsLandRelief,
      hydrogenGridRelief: hydrogenStep.ledger.hydrogenGridRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextGeothermalMemory[regionId] || null,
    });
    nextGeothermalMemory[regionId] = geoStep.next;
    geothermalLedgers[regionId] = geoStep.ledger;

    const heatDecarbStep = advanceRegionalIndustrialHeatDecarbon({
      regionId,
      netEmissionsIndex: emissionsStep.ledger.netEmissionsIndex,
      geothermalBand: geoStep.ledger.band,
      mineralsSupplyRelief: mineralsStep.ledger.mineralsSupplyRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextIndustrialHeatMemory[regionId] || null,
    });
    nextIndustrialHeatMemory[regionId] = heatDecarbStep.next;
    industrialHeatDecarbLedgers[regionId] = heatDecarbStep.ledger;

    const blueCarbonStep = computeRegionalBlueCarbonCoastalLedger({
      regionId,
      climateHazardPressure: climatePressure,
      offshoreRenewableRelief: offshoreStep.ledger.offshoreRenewableRelief,
      soilCarbonLandRelief: soilStep.ledger.soilCarbonLandRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextBlueCarbonMemory[regionId] || null,
    });
    nextBlueCarbonMemory[regionId] = blueCarbonStep.next;
    blueCarbonCoastalLedgers[regionId] = blueCarbonStep.ledger;

    const shoreMarineStep = advanceRegionalShoreMarineEnergy({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      blueCarbonBand: blueCarbonStep.ledger.band,
      industrialHeatRelief: heatDecarbStep.ledger.industrialHeatRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextShoreMarineMemory[regionId] || null,
    });
    nextShoreMarineMemory[regionId] = shoreMarineStep.next;
    shoreMarineEnergyLedgers[regionId] = shoreMarineStep.ledger;

    const landfillStep = computeRegionalLandfillWasteEnergyLedger({
      regionId,
      circularRecoveryRelief: circularStep.ledger.circularRelief,
      ccsEmissionsRelief: ccsStep.ledger.ccsEmissionsRelief,
      netEmissionsIndex: emissionsStep.ledger.netEmissionsIndex,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextLandfillWasteMemory[regionId] || null,
    });
    nextLandfillWasteMemory[regionId] = landfillStep.next;
    landfillWasteEnergyLedgers[regionId] = landfillStep.ledger;

    const districtHeatStep = advanceRegionalDistrictRenewableHeat({
      regionId,
      gridStressPoints: gridStress.stressPoints,
      landfillBand: landfillStep.ledger.band,
      geothermalHeatRelief: geoStep.ledger.geothermalHeatRelief,
      completedProjectTypes: inputs.completedProjectTypes || [],
      prev: nextDistrictHeatMemory[regionId] || null,
    });
    nextDistrictHeatMemory[regionId] = districtHeatStep.next;
    districtRenewableHeatLedgers[regionId] = districtHeatStep.ledger;

    const activeRules = V1014_ENVIRONMENTAL_RULES.filter(rule => {
      if (rule.regionId !== regionId) return false;
      const str = rule.industry === 'mining' ? miningStr : rule.industry === 'energy' ? energyStr : mfgStr;
      return str >= rule.triggerStrengthMin;
    }).slice(0, V1014_LIMITS.maxActiveConstraints);

    let pressure = activeRules.reduce((a, r) => a + r.constraintLoss * 100, 0) + energyStress + climatePressure;
    pressure += gridScenario.stressModifier;
    pressure += permitStep.ledger.pressureAdd;
    pressure += waterStep.ledger.pressureAdd;
    pressure -= emissionsStep.ledger.pressureRelief;
    pressure -= biodiversityStep.ledger.landStewardshipRelief;
    pressure -= circularStep.ledger.circularRelief;
    pressure -= hydrogenStep.ledger.hydrogenGridRelief;
    pressure -= mineralsStep.ledger.mineralsSupplyRelief;
    pressure -= offshoreStep.ledger.offshoreRenewableRelief;
    pressure -= demandStep.ledger.demandFlexRelief;
    pressure -= ccsStep.ledger.ccsEmissionsRelief;
    pressure -= firmingStep.ledger.gridFirmingRelief;
    pressure -= rezStep.ledger.rezSpillRelief;
    pressure -= bushfireStep.ledger.bushfireGridRelief;
    pressure -= derStep.ledger.rooftopDerRelief;
    pressure -= v2gStep.ledger.evV2gGridRelief;
    pressure -= agriStep.ledger.agrivoltaicsLandRelief;
    pressure -= soilStep.ledger.soilCarbonLandRelief;
    pressure -= geoStep.ledger.geothermalHeatRelief;
    pressure -= heatDecarbStep.ledger.industrialHeatRelief;
    pressure -= blueCarbonStep.ledger.blueCarbonCoastalRelief;
    pressure -= shoreMarineStep.ledger.shoreMarineEnergyRelief;
    pressure -= landfillStep.ledger.landfillMethaneRelief;
    pressure -= districtHeatStep.ledger.districtHeatRelief;
    if (biodiversityStep.ledger.band === 'critical_loss') pressure += 5;
    pressure -= gridRecovery.pressureRelief;
    pressure -= storageFlex.gridStressRelief;
    pressure -= activeRules.reduce((a, r) => a + r.renewableRelief * Math.min(1, renewableShareScore / 55), 0) * 12;
    pressure += sites.filter(s => s.environmentalRisk === 'high').length * 4;
    pressure = v1014Clamp(pressure, 0, 100);

    nextHyst[regionId] = { extractionScore, renewableScore: renewableShareScore, pressure };

    const extractionBand = v1014BandExtraction(extractionScore);
    const renewableBand = v1014BandRenewable(renewableShareScore / 100);

    const climateTransition = computeClimateTransitionProfile({
      renewableShareScore,
      extractionScore,
      environmentalPressure: pressure,
      gridStressPoints: gridStress.stressPoints,
      renewableBand,
    });
    pressure -= climateTransition.momentum > 0 ? climateTransition.momentum * 3 : 0;
    pressure = v1014Clamp(pressure, 0, 100);

    const constraintBand = v1014BandConstraint(pressure);

    const evidence = [
      `Extraction score ${extractionScore} (${extractionBand}) from sectors mining ${miningSec.toFixed(0)} / energy ${energySec.toFixed(0)}`,
      `Renewable share score ${renewableShareScore.toFixed(0)} (${renewableBand})`,
      gridStress.summary,
      gridRecovery.summary,
      extractionEfficiency.summary,
      `Grid scenario ${gridScenario.label}`,
      climateTransition.summary,
      storageFlex.summary,
      permitStep.ledger.summary,
      emissionsStep.ledger.summary,
      waterStep.ledger.summary,
      biodiversityStep.ledger.summary,
      circularStep.ledger.summary,
      hydrogenStep.ledger.summary,
      mineralsStep.ledger.summary,
      offshoreStep.ledger.summary,
      demandStep.ledger.summary,
      ccsStep.ledger.summary,
      firmingStep.ledger.summary,
      rezStep.ledger.summary,
      bushfireStep.ledger.summary,
      derStep.ledger.summary,
      v2gStep.ledger.summary,
      agriStep.ledger.summary,
      soilStep.ledger.summary,
      geoStep.ledger.summary,
      heatDecarbStep.ledger.summary,
      blueCarbonStep.ledger.summary,
      shoreMarineStep.ledger.summary,
      landfillStep.ledger.summary,
      districtHeatStep.ledger.summary,
      climateHazards.length ? `${climateHazards.length} active climate hazard signal(s)` : 'No climate hazards from crises',
      activeRules.length ? `${activeRules.length} environmental rule(s) active` : 'No environmental rules triggered',
    ];

    for (const rule of activeRules) {
      const str = rule.industry === 'mining' ? miningStr : rule.industry === 'energy' ? energyStr : mfgStr;
      const relief = rule.renewableRelief * Math.min(1, renewableShareScore / 60);
      const loss = v1014Clamp((rule.constraintLoss * 100 * (str / 100) - relief * 10), 0, 22);
      const delta = -v1014Round(loss, 1);
      if (delta >= -0.5) continue;
      modifiers.push({
        regionId,
        industry: rule.industry,
        delta: v1014Clamp(delta, V1014_LIMITS.modifierFloor, V1014_LIMITS.modifierCap),
        provenance: 'v1014_environmental_constraint',
        ruleId: rule.id,
        explanation: rule.summary,
      });
    }

    if (renewableBand === 'leading' && energyStr > 40) {
      modifiers.push({
        regionId,
        industry: 'energy',
        delta: v1014Clamp(4 + renewableShareScore / 40, 0, V1014_LIMITS.modifierCap),
        provenance: 'v1014_renewable_lift',
        ruleId: `ren_lift_${regionId}`,
        explanation: 'Leading renewable share supports cleaner energy industry output.',
      });
    }

    if (climateTransition.stage === 'net_zero_pathway' && energyStr > 30) {
      modifiers.push({
        regionId,
        industry: 'energy',
        delta: v1014Clamp(2 + climateTransition.depth / 40, 0, V1014_LIMITS.modifierCap),
        provenance: 'v1014_climate_transition_depth',
        ruleId: `clim_tr_${regionId}`,
        explanation: climateTransition.summary,
      });
    }

    if (Math.abs(extractionEfficiency.miningModifierBoost) >= 0.5 && miningStr > 20) {
      modifiers.push({
        regionId,
        industry: 'mining',
        delta: v1014Clamp(extractionEfficiency.miningModifierBoost, V1014_LIMITS.modifierFloor, V1014_LIMITS.modifierCap),
        provenance: 'v1014_extraction_efficiency',
        ruleId: `ext_eff_${regionId}`,
        explanation: extractionEfficiency.summary,
      });
    }

    const energyMod = modifiers.find(m => m.regionId === regionId && m.industry === 'energy')?.delta ?? null;
    householdHintLists.push(
      buildHouseholdEnergyHints({
        regionId,
        constraintBand,
        environmentalPressure: pressure,
        extractionBand,
        renewableBand,
        energyIndustryModifier: energyMod,
      }),
    );

    regions[regionId] = {
      regionId,
      extractionBand,
      renewableBand,
      constraintBand,
      extractionScore,
      renewableShareScore,
      environmentalPressure: v1014Round(pressure, 1),
      gridStressBand: gridStress.band,
      gridStressPoints: Math.max(0, v1014Round(gridStress.stressPoints - storageFlex.gridStressRelief, 1)),
      gridRecoveryBand: gridRecovery.band,
      gridRecoveryPoints: gridRecovery.recoveryPoints,
      extractionEfficiencyScore: extractionEfficiency.score,
      extractionEfficiencyBand: extractionEfficiency.band,
      activeGridScenarioId: gridScenario.id,
      climateTransitionStage: climateTransition.stage,
      climateTransitionDepth: climateTransition.depth,
      storageFlexibilityBand: storageFlex.band,
      storageStressRelief: storageFlex.gridStressRelief,
      permitUtilizationBand: permitStep.ledger.band,
      carbonCreditBand: emissionsStep.ledger.band,
      emissionsPressureRelief: emissionsStep.ledger.pressureRelief,
      waterStressBand: waterStep.ledger.band,
      biodiversityStewardshipBand: biodiversityStep.ledger.band,
      landStewardshipRelief: biodiversityStep.ledger.landStewardshipRelief,
      circularRecoveryBand: circularStep.ledger.band,
      circularRecoveryRelief: circularStep.ledger.circularRelief,
      hydrogenExportBand: hydrogenStep.ledger.band,
      hydrogenGridRelief: hydrogenStep.ledger.hydrogenGridRelief,
      mineralsSecurityBand: mineralsStep.ledger.band,
      mineralsSupplyRelief: mineralsStep.ledger.mineralsSupplyRelief,
      offshoreMarineBand: offshoreStep.ledger.band,
      offshoreRenewableRelief: offshoreStep.ledger.offshoreRenewableRelief,
      demandResponseBand: demandStep.ledger.band,
      demandFlexRelief: demandStep.ledger.demandFlexRelief,
      ccsHubBand: ccsStep.ledger.band,
      ccsEmissionsRelief: ccsStep.ledger.ccsEmissionsRelief,
      gridFirmingBand: firmingStep.ledger.band,
      gridFirmingRelief: firmingStep.ledger.gridFirmingRelief,
      rezTransmissionBand: rezStep.ledger.band,
      rezSpillRelief: rezStep.ledger.rezSpillRelief,
      bushfireResilienceBand: bushfireStep.ledger.band,
      bushfireGridRelief: bushfireStep.ledger.bushfireGridRelief,
      rooftopDerBand: derStep.ledger.band,
      rooftopDerRelief: derStep.ledger.rooftopDerRelief,
      evV2gFleetBand: v2gStep.ledger.band,
      evV2gGridRelief: v2gStep.ledger.evV2gGridRelief,
      agrivoltaicsBand: agriStep.ledger.band,
      agrivoltaicsLandRelief: agriStep.ledger.agrivoltaicsLandRelief,
      soilCarbonLandBand: soilStep.ledger.band,
      soilCarbonLandRelief: soilStep.ledger.soilCarbonLandRelief,
      geothermalBand: geoStep.ledger.band,
      geothermalHeatRelief: geoStep.ledger.geothermalHeatRelief,
      industrialHeatDecarbBand: heatDecarbStep.ledger.band,
      industrialHeatRelief: heatDecarbStep.ledger.industrialHeatRelief,
      blueCarbonCoastalBand: blueCarbonStep.ledger.band,
      blueCarbonCoastalRelief: blueCarbonStep.ledger.blueCarbonCoastalRelief,
      shoreMarineEnergyBand: shoreMarineStep.ledger.band,
      shoreMarineEnergyRelief: shoreMarineStep.ledger.shoreMarineEnergyRelief,
      landfillWasteEnergyBand: landfillStep.ledger.band,
      landfillMethaneRelief: landfillStep.ledger.landfillMethaneRelief,
      districtRenewableHeatBand: districtHeatStep.ledger.band,
      districtHeatRelief: districtHeatStep.ledger.districtHeatRelief,
      activeClimateHazards: climateHazards,
      activeRuleIds: activeRules.map(r => r.id),
      activeSiteIds: sites.slice(0, 6).map(s => s.id),
      activeAssetIds: assets.slice(0, 6).map(a => a.id),
      evidence: evidence.slice(0, V1014_LIMITS.maxEvidence),
    };

    const prevProfile = prev?.regions?.[regionId];
    if (prevProfile) {
      (['extractionBand', 'renewableBand', 'constraintBand'] as const).forEach(field => {
        if (prevProfile[field] !== regions[regionId][field]) {
          transitions.push({
            id: `ie14_${regionId}_${field}_${turn}`,
            turn,
            regionId,
            field,
            from: prevProfile[field],
            to: regions[regionId][field],
            explanation: evidence[0],
          });
        }
      });
    }
  }

  const regionList = Object.values(regions);
  const spill = computeInterRegionalSpillover(regions);
  const mergedRegions = spill.adjustedRegions;
  const interRegionalFlows = spill.flows;
  const turnSimulationDigest = `t${turn}|flows${interRegionalFlows.length}|hash${inputHash}`;

  const regionListMerged = Object.values(mergedRegions);
  const nationalRenewableShare = regionListMerged.length ? v1014Round(regionListMerged.reduce((a, r) => a + r.renewableShareScore, 0) / regionListMerged.length / 100, 3) : 0;
  const nationalExtractionIntensity = regionListMerged.length ? v1014Round(regionListMerged.reduce((a, r) => a + r.extractionScore, 0) / regionListMerged.length, 1) : 0;
  const topConstrainedRegions = regionListMerged.sort((a, b) => b.environmentalPressure - a.environmentalPressure).slice(0, 3).map(r => r.regionId);
  const topRenewableRegions = regionListMerged.sort((a, b) => b.renewableShareScore - a.renewableShareScore).slice(0, 3).map(r => r.regionId);
  const domainCounts: Record<string, number> = {};
  modifiers.forEach(m => {
    const rule = V1014_ENVIRONMENTAL_RULES_BY_ID[m.ruleId];
    if (rule) domainCounts[rule.domain] = (domainCounts[rule.domain] || 0) + 1;
  });
  const primaryEnvironmentalDomain = Object.entries(domainCounts).sort((a, b) => b[1] - a[1])[0]?.[0] as V1014EnvironmentalDomain | undefined;

  const national = {
    extractionBand: v1014BandExtraction(nationalExtractionIntensity),
    renewableBand: v1014BandRenewable(nationalRenewableShare),
    constraintBand: v1014BandConstraint(regionListMerged.reduce((a, r) => a + r.environmentalPressure, 0) / Math.max(1, regionListMerged.length)),
    nationalRenewableShare,
    nationalExtractionIntensity,
    topConstrainedRegions,
    topRenewableRegions,
    primaryEnvironmentalDomain: primaryEnvironmentalDomain || null,
    summary: `National extraction ${v1014BandExtraction(nationalExtractionIntensity)}, renewables ${v1014BandRenewable(nationalRenewableShare)}, environmental constraint ${v1014BandConstraint(regionListMerged.reduce((a, r) => a + r.environmentalPressure, 0) / Math.max(1, regionListMerged.length))}.`,
  };

  const history = [...persisted.history, ...(transitions.length ? [{ id: `ie14_hist_${turn}`, turn, kind: 'transition', summary: `${transitions.length} regional band change(s)` }] : [])].slice(-V1014_LIMITS.maxHistory);

  const state: IndustrialEnergyEnvironmentalState = {
    schemaVersion: V1014_SCHEMA_VERSION,
    revision: persisted.revision + 1,
    turn,
    inputHash,
    regions: mergedRegions,
    national,
    industryModifiers: modifiers.slice(0, 120),
    householdEnergyHints: mergeHouseholdEnergyHints(householdHintLists).slice(0, 48),
    interRegionalFlows,
    turnSimulationDigest,
    regionalPermitLedgers: permitLedgers,
    regionalEmissionsLedgers: emissionsLedgers,
    regionalWaterLedgers: waterLedgers,
    regionalBiodiversityLedgers: biodiversityLedgers,
    regionalCircularLedgers: circularLedgers,
    regionalHydrogenLedgers: hydrogenLedgers,
    regionalMineralsLedgers: mineralsLedgers,
    regionalOffshoreLedgers: offshoreLedgers,
    regionalDemandResponseLedgers: demandResponseLedgers,
    regionalCcsLedgers: ccsLedgers,
    regionalFirmingLedgers: firmingLedgers,
    regionalRezLedgers: rezLedgers,
    regionalBushfireLedgers: bushfireLedgers,
    regionalRooftopDerLedgers: rooftopDerLedgers,
    regionalEvV2gLedgers: evV2gLedgers,
    regionalAgrivoltaicsLedgers: agrivoltaicsLedgers,
    regionalSoilCarbonLandLedgers: soilCarbonLandLedgers,
    regionalGeothermalLedgers: geothermalLedgers,
    regionalIndustrialHeatDecarbLedgers: industrialHeatDecarbLedgers,
    regionalBlueCarbonCoastalLedgers: blueCarbonCoastalLedgers,
    regionalShoreMarineEnergyLedgers: shoreMarineEnergyLedgers,
    regionalLandfillWasteEnergyLedgers: landfillWasteEnergyLedgers,
    regionalDistrictRenewableHeatLedgers: districtRenewableHeatLedgers,
    transitions: transitions.slice(0, 24),
    history,
  };

  const nextPersisted: IndustrialEnergyEnvironmentalPersisted = {
    schemaVersion: V1014_SCHEMA_VERSION,
    revision: state.revision,
    initializedTurn: persisted.initializedTurn ?? turn,
    lastInputHash: inputHash,
    regionalHysteresis: nextHyst,
    regionalPermitMemory: nextPermitMemory,
    regionalCarbonMemory: nextCarbonMemory,
    regionalWaterMemory: nextWaterMemory,
    regionalBiodiversityMemory: nextBiodiversityMemory,
    regionalCircularMemory: nextCircularMemory,
    regionalHydrogenMemory: nextHydrogenMemory,
    regionalMineralsMemory: nextMineralsMemory,
    regionalOffshoreMemory: nextOffshoreMemory,
    regionalDemandResponseMemory: nextDemandResponseMemory,
    regionalCcsMemory: nextCcsMemory,
    regionalFirmingMemory: nextFirmingMemory,
    regionalRezMemory: nextRezMemory,
    regionalBushfireMemory: nextBushfireMemory,
    regionalRooftopDerMemory: nextRooftopDerMemory,
    regionalEvV2gMemory: nextEvV2gMemory,
    regionalAgrivoltaicsMemory: nextAgrivoltaicsMemory,
    regionalSoilCarbonLandMemory: nextSoilCarbonLandMemory,
    regionalGeothermalMemory: nextGeothermalMemory,
    regionalIndustrialHeatMemory: nextIndustrialHeatMemory,
    regionalBlueCarbonMemory: nextBlueCarbonMemory,
    regionalShoreMarineMemory: nextShoreMarineMemory,
    regionalLandfillWasteMemory: nextLandfillWasteMemory,
    regionalDistrictHeatMemory: nextDistrictHeatMemory,
    history,
  };
  return { state, persisted: nextPersisted };
}

export function advanceIndustrialEnergyEnvironmentalTurn(params: {
  turn: number;
  enabled: boolean;
  gameState: any;
  gameSettings: any;
  livingRegions: any;
  nationalSystems: NationalSystemsState | null;
  industries: IndustriesSupplyChainsState | null;
  regionalFactions: RegionalFactionsState | null;
  persisted?: IndustrialEnergyEnvironmentalPersisted | null;
  prev?: IndustrialEnergyEnvironmentalState | null;
}): { state: IndustrialEnergyEnvironmentalState; persisted: IndustrialEnergyEnvironmentalPersisted } {
  const inputs = buildIndustrialEnergyEnvironmentalInputs(params);
  return computeIndustrialEnergyEnvironmentalState(inputs, params.persisted ?? null, params.prev ?? null);
}

export { scoreAgent13EnergyEnvironmentGIAlignment };

export function buildIndustrialEnergyIndustryModifiers(state: IndustrialEnergyEnvironmentalState | null | undefined): IndustriesInputs['modifiers'] {
  if (!state || !state.industryModifiers.length) return undefined;
  const out: IndustriesInputs['modifiers'] = {};
  for (const m of state.industryModifiers) {
    out[m.regionId] = out[m.regionId] || {};
    const prev = out[m.regionId]![m.industry] || 0;
    out[m.regionId]![m.industry] = v1014Clamp(prev + m.delta, V1014_LIMITS.modifierFloor, V1014_LIMITS.modifierCap);
  }
  return out;
}

export function mergeIndustryModifiers(...mods: Array<IndustriesInputs['modifiers'] | undefined>): IndustriesInputs['modifiers'] {
  const out: IndustriesInputs['modifiers'] = {};
  for (const m of mods) {
    if (!m) continue;
    for (const [regionId, inds] of Object.entries(m)) {
      out[regionId] = out[regionId] || {};
      for (const [ind, delta] of Object.entries(inds || {})) {
        const k = ind as keyof NonNullable<IndustriesInputs['modifiers']>[string];
        const prev = out[regionId]![k as 'mining'] || 0;
        out[regionId]![k as 'mining'] = v1014Clamp(prev + Number(delta), V1014_LIMITS.modifierFloor, V1014_LIMITS.modifierCap);
      }
    }
  }
  return Object.keys(out).length ? out : undefined;
}

